gpJ(){return"Model management"},
gpL(){return"Auto update check"},
gpX(){return"Transformer (40%)"},
gpV(){return"Statistical analysis (25%)"},
gpW(){return"Stylometry (20%)"},
gpT(){return"Adversarial defense (15%)"},
gpU(){return"Report LLM (optional)"},
